// Type declarations for the xljs runtime.
// Generated by `xljs init`; keep next to your scripts for editor completion.

export {};

declare global {
  // ------------------------------------------------------------------ xljs

  interface Xljs {
    /** xljs のバージョン */
    readonly version: string;
    /** スクリプトに渡された引数（埋め込み exe ではドロップしたファイルのパスなど） */
    readonly args: string[];
    /** 実行中のスクリプト（埋め込み exe では exe と同じフォルダの仮想パス）の絶対パス */
    readonly script: string;
    /** スクリプトのあるフォルダ */
    readonly scriptDir: string;
    /** "windows" / "linux" / "darwin" */
    readonly platform: string;
    /** 使用中の UI: "native" / "console" / "mock" */
    readonly ui: string;
    /** ダイアログのタイトル（既定はスクリプト名） */
    title: string;
    /** 終了コードを指定してスクリプトを終了する */
    exit(code?: number): never;
    /** 環境変数を取得（未定義なら null） */
    env(name: string): string | null;
    /** console.log と同じ形式で値を文字列化する */
    inspect(value: unknown, options?: { depth?: number }): string;
  }
  const xljs: Xljs;

  interface Console {
    log(...data: any[]): void;
    info(...data: any[]): void;
    debug(...data: any[]): void;
    warn(...data: any[]): void;
    error(...data: any[]): void;
    trace(...data: any[]): void;
    dir(item?: any, options?: { depth?: number }): void;
    table(data: any, columns?: string[]): void;
    assert(condition?: boolean, ...data: any[]): void;
    time(label?: string): void;
    timeLog(label?: string, ...data: any[]): void;
    timeEnd(label?: string): void;
    count(label?: string): void;
    countReset(label?: string): void;
    group(...data: any[]): void;
    groupCollapsed(...data: any[]): void;
    groupEnd(): void;
  }
  var console: Console;

  function setTimeout(handler: (...args: any[]) => void, timeout?: number, ...args: any[]): number;
  function setInterval(handler: (...args: any[]) => void, timeout?: number, ...args: any[]): number;
  function setImmediate(handler: (...args: any[]) => void, ...args: any[]): number;
  function clearTimeout(id?: number): void;
  function clearInterval(id?: number): void;
  function clearImmediate(id?: number): void;
  function queueMicrotask(callback: () => void): void;
  function structuredClone<T>(value: T): T;
  function atob(data: string): string;
  function btoa(data: string): string;

  class TextEncoder {
    readonly encoding: "utf-8";
    encode(input?: string): Uint8Array;
  }
  class TextDecoder {
    /** "utf-8", "shift_jis", "euc-jp", "utf-16le" など */
    constructor(label?: string, options?: { fatal?: boolean; ignoreBOM?: boolean });
    readonly encoding: string;
    decode(input?: ArrayBuffer | ArrayBufferView): string;
  }

  class DOMException extends Error {
    constructor(message?: string, name?: string);
  }
  /** xljs.exit と同じ */
  function exit(code?: number): never;
  /** 指定ミリ秒待つ */
  function sleep(ms: number): Promise<void>;

  // ------------------------------------------------------------------ dialogs

  function alert(message?: unknown): void;
  function confirm(message?: unknown): boolean;
  /** キャンセル時は null */
  function prompt(message?: unknown, defaultValue?: string): string | null;

  type WellKnownDirectory = "desktop" | "documents" | "downloads" | "music" | "pictures" | "videos";

  interface FilePickerAcceptType {
    description?: string;
    /** { "MIME": [".xlsx"] }、[".xlsx", ".xlsm"]、".csv" のいずれか */
    accept: Record<string, string | string[]> | string[] | string;
  }

  interface FilePickerOptions {
    types?: FilePickerAcceptType[];
    excludeAcceptAllOption?: boolean;
    startIn?: WellKnownDirectory | string | FileSystemHandle;
    /** ダイアログのタイトル（xljs 拡張） */
    title?: string;
    id?: string;
  }
  interface OpenFilePickerOptions extends FilePickerOptions {
    multiple?: boolean;
  }
  interface SaveFilePickerOptions extends FilePickerOptions {
    suggestedName?: string;
  }
  interface DirectoryPickerOptions {
    startIn?: WellKnownDirectory | string | FileSystemHandle;
    title?: string;
    id?: string;
    mode?: "read" | "readwrite";
  }

  /** ファイルを選択する。キャンセル時は空配列 */
  function showOpenFilePicker(options?: OpenFilePickerOptions): Promise<FileSystemFileHandle[]>;
  /** 保存先を選択する。キャンセル時は null */
  function showSaveFilePicker(options?: SaveFilePickerOptions): Promise<FileSystemFileHandle | null>;
  /** フォルダを選択する。キャンセル時は null */
  function showDirectoryPicker(options?: DirectoryPickerOptions): Promise<FileSystemDirectoryHandle | null>;

  // ------------------------------------------------------------------ ui

  interface ProgressOptions {
    title?: string;
    /** 総数。省略または 0 で総数不明（マーキー表示） */
    total?: number;
    message?: string;
    /** キャンセルボタンを出すか（既定 true） */
    cancellable?: boolean;
  }

  interface Progress {
    total: number;
    readonly done: number;
    message: string;
    /** ユーザーがキャンセル（またはコンソールで Ctrl+C）したか */
    readonly cancelled: boolean;
    /** 完了件数とメッセージを更新する */
    update(done: number, message?: string): this;
    /** 完了件数を 1 増やす */
    increment(message?: string): this;
    close(): void;
  }

  interface WithProgressOptions<T> extends ProgressOptions {
    /** 各要素の表示ラベル。既定はハンドルなら relativePath */
    label?: (item: T, index: number) => string;
  }

  interface Ui {
    alert: typeof alert;
    confirm: typeof confirm;
    prompt: typeof prompt;
    showOpenFilePicker: typeof showOpenFilePicker;
    showSaveFilePicker: typeof showSaveFilePicker;
    showDirectoryPicker: typeof showDirectoryPicker;
    /** 進捗表示を開く */
    progress(options?: ProgressOptions | string): Progress;
    /** 反復しながら進捗を表示する。キャンセルされると反復が途中で終わる */
    withProgress<T>(iterable: Iterable<T>, options?: WithProgressOptions<T> | string): Generator<T, void, undefined>;
    withProgress<T>(iterable: AsyncIterable<T>, options?: WithProgressOptions<T> | string): AsyncIterableIterator<T>;
    /** 直近の進捗表示がキャンセルされたか */
    readonly cancelled: boolean;
    /** エラーダイアログを表示する */
    error(message: unknown): void;
  }
  const ui: Ui;

  // ------------------------------------------------------------------ files

  interface FileSystemHandle {
    readonly kind: "file" | "directory";
    readonly name: string;
    /** 絶対パス（xljs 拡張） */
    readonly path: string;
    /** walk() の起点からの相対パス（xljs 拡張） */
    readonly relativePath: string;
    isSameEntry(other: FileSystemHandle): Promise<boolean>;
    /** 存在するか（xljs 拡張） */
    exists(): boolean;
  }

  interface FileStat {
    isFile: boolean;
    isDirectory: boolean;
    size: number;
    mtimeMs: number;
  }

  type WriteData = string | ArrayBuffer | ArrayBufferView | Blob;

  interface FileSystemWritableFileStream {
    write(data: WriteData | { type: "write"; data: WriteData; position?: number } | { type: "seek"; position: number } | { type: "truncate"; size: number }): Promise<void>;
    seek(position: number): Promise<void>;
    truncate(size: number): Promise<void>;
    close(): Promise<void>;
    abort(): Promise<void>;
  }

  interface FileSystemFileHandle extends FileSystemHandle {
    readonly kind: "file";
    getFile(): Promise<File>;
    createWritable(options?: { keepExistingData?: boolean }): Promise<FileSystemWritableFileStream>;
    // xljs extensions
    stat(): FileStat | null;
    /** 既定 "auto"（BOM / UTF-8 / CP932 を自動判定） */
    readText(encoding?: Encoding): string;
    readBytes(): ArrayBuffer;
    writeText(text: string, encoding?: Encoding): this;
    appendText(text: string, encoding?: Encoding): this;
    writeBytes(data: ArrayBuffer | ArrayBufferView): this;
  }

  interface WalkOptions {
    /** 対象パターン。"/" を含まないパターンは任意の階層のファイル名に一致（大文字小文字無視） */
    glob?: string | string[];
    include?: string | string[];
    /** 除外パターン。フォルダが一致するとその中も除外 */
    exclude?: string | string[];
    /** フォルダも返す（既定 false） */
    directories?: boolean;
    /** ファイルを返す（既定 true） */
    files?: boolean;
  }

  interface WalkResult<T extends FileSystemHandle = FileSystemHandle> extends Iterable<T>, AsyncIterable<T> {
    readonly length: number;
    toArray(): T[];
    map<U>(fn: (h: T, i: number) => U): U[];
    filter(fn: (h: T, i: number) => boolean): T[];
    forEach(fn: (h: T, i: number) => void): void;
  }

  interface FileSystemDirectoryHandle extends FileSystemHandle, AsyncIterable<[string, FileSystemHandle]> {
    readonly kind: "directory";
    getFileHandle(name: string, options?: { create?: boolean }): Promise<FileSystemFileHandle>;
    getDirectoryHandle(name: string, options?: { create?: boolean }): Promise<FileSystemDirectoryHandle>;
    removeEntry(name: string, options?: { recursive?: boolean }): Promise<void>;
    resolve(possibleDescendant: FileSystemHandle): Promise<string[] | null>;
    entries(): AsyncIterableIterator<[string, FileSystemFileHandle | FileSystemDirectoryHandle]>;
    keys(): AsyncIterableIterator<string>;
    values(): AsyncIterableIterator<FileSystemFileHandle | FileSystemDirectoryHandle>;
    // xljs extensions
    /** サブフォルダを含めて走査する */
    walk(options?: WalkOptions | string | string[]): WalkResult<FileSystemFileHandle>;
    /** 直下の項目を同期的に列挙する */
    list(): (FileSystemFileHandle | FileSystemDirectoryHandle)[];
    /** 直下のファイルのハンドル（存在確認なし） */
    file(name: string): FileSystemFileHandle;
    /** 直下のフォルダのハンドル（存在確認なし） */
    dir(name: string): FileSystemDirectoryHandle;
  }

  var FileSystemHandle: { prototype: FileSystemHandle };
  var FileSystemFileHandle: { prototype: FileSystemFileHandle; new (path: string): FileSystemFileHandle };
  var FileSystemDirectoryHandle: { prototype: FileSystemDirectoryHandle; new (path: string): FileSystemDirectoryHandle };

  interface Blob {
    readonly size: number;
    readonly type: string;
    arrayBuffer(): Promise<ArrayBuffer>;
    bytes(): Promise<Uint8Array>;
    /** encoding は xljs 拡張（既定 "utf8"、"auto" で自動判定） */
    text(encoding?: Encoding): Promise<string>;
    slice(start?: number, end?: number, contentType?: string): Blob;
  }
  var Blob: { prototype: Blob; new (parts?: (string | ArrayBuffer | ArrayBufferView | Blob)[], options?: { type?: string }): Blob };

  interface File extends Blob {
    readonly name: string;
    readonly lastModified: number;
    /** ディスク上のパス（xljs 拡張。メモリ上の File では null） */
    readonly path: string | null;
  }
  var File: { prototype: File; new (parts: (string | ArrayBuffer | ArrayBufferView | Blob)[], name: string, options?: { type?: string; lastModified?: number }): File };

  type PathLike = string | FileSystemHandle | File;

  /**
   * "utf8" / "utf8bom" / "cp932"（= "shift_jis", "sjis"）/ "euc-jp" / "iso-2022-jp" / "utf16le" / "utf16be" / "auto"
   */
  type Encoding = string;

  interface Fs {
    file(path: PathLike): FileSystemFileHandle;
    dir(path: PathLike): FileSystemDirectoryHandle;
    /** 存在しなければ NotFoundError */
    getFileHandle(path: PathLike): Promise<FileSystemFileHandle>;
    getDirectoryHandle(path: PathLike): Promise<FileSystemDirectoryHandle>;
    exists(path: PathLike): boolean;
    isFile(path: PathLike): boolean;
    isDirectory(path: PathLike): boolean;
    stat(path: PathLike): FileStat | null;
    readText(path: PathLike, encoding?: Encoding): string;
    writeText(path: PathLike, text: string, encoding?: Encoding): void;
    appendText(path: PathLike, text: string, encoding?: Encoding): void;
    readBytes(path: PathLike): ArrayBuffer;
    writeBytes(path: PathLike, data: ArrayBuffer | ArrayBufferView | string): void;
    /** JSON ファイルを読む（BOM・CP932 も自動判定） */
    readJSON<T = any>(src: PathLike | Blob, options?: JsonReadOptions): T;
    /** JSON で書き出す。日付は既定でローカル時刻＋オフセット（例 2026-04-01T09:00:00+09:00） */
    writeJSON(dest: PathLike, value: unknown, options?: JsonWriteOptions | number): void;
    /** JSON Lines（1 行 1 JSON）を読む */
    readJSONL<T = any>(src: PathLike | Blob, options?: JsonReadOptions): T[];
    /** 配列を JSON Lines で書き出す */
    writeJSONL(dest: PathLike, rows: Iterable<unknown>, options?: JsonWriteOptions): void;
    /** 直下の名前一覧 */
    list(path?: PathLike): string[];
    walk(path: PathLike, options?: WalkOptions | string | string[]): WalkResult<FileSystemFileHandle>;
    /** カレントフォルダ（または cwd）からの glob */
    glob(pattern: string, options?: { cwd?: PathLike; exclude?: string | string[] }): FileSystemFileHandle[];
    mkdir(path: PathLike): void;
    remove(path: PathLike, options?: { recursive?: boolean }): void;
    rename(from: PathLike, to: PathLike): void;
    move(from: PathLike, to: PathLike): void;
    copy(from: PathLike, to: PathLike): void;
    cwd(): string;
    chdir(path: PathLike): void;
  }
  const fs: Fs;

  interface JsonReadOptions {
    /** 既定 "auto" */
    encoding?: Encoding;
    /** ISO 形式の日時文字列を Date に戻す（既定 false） */
    dates?: boolean;
  }
  interface JsonWriteOptions {
    /** インデント（既定 2。JSON Lines では無視） */
    space?: number | string;
    /** 既定 "utf8" */
    encoding?: Encoding;
    /** "local"（既定）: 2026-04-01T09:00:00+09:00、"iso": JSON.stringify と同じ UTC 表記 */
    dates?: "local" | "iso";
    /** 追記する（writeJSONL のみ） */
    append?: boolean;
  }

  interface Shell {
    /** エクスプローラーでファイルを選択した状態で表示する（複数可。フォルダが違えばフォルダごとに開く） */
    showItemInFolder(...items: (PathLike | PathLike[])[]): void;
    /** showItemInFolder と同じ */
    showInFolder(...items: (PathLike | PathLike[])[]): void;
    /** ファイル・フォルダを既定のアプリで開く */
    openPath(target: PathLike): void;
    /** URL を既定のブラウザで開く */
    openExternal(url: string): void;
    /** URL なら openExternal、それ以外は openPath */
    open(target: PathLike): void;
  }
  const shell: Shell;

  interface Path {
    readonly sep: string;
    join(...parts: PathLike[]): string;
    resolve(...parts: PathLike[]): string;
    dirname(p: PathLike): string;
    basename(p: PathLike, ext?: string): string;
    extname(p: PathLike): string;
    normalize(p: PathLike): string;
    isAbsolute(p: PathLike): boolean;
    relative(from: PathLike, to: PathLike): string;
  }
  const path: Path;

  // ------------------------------------------------------------------ csv

  interface CsvParseOptions {
    /** 1 行目を見出しとしてオブジェクトにする（既定 true） */
    header?: boolean;
    delimiter?: string;
    /** header: false のときの列名 */
    columns?: string[];
    /** 数値・真偽値に変換し、空欄を null にする */
    cast?: boolean;
    trim?: boolean;
    skipEmptyLines?: boolean;
    comment?: string;
  }
  interface CsvReadOptions extends CsvParseOptions {
    /** 既定 "auto" */
    encoding?: Encoding;
  }
  interface CsvStringifyOptions {
    header?: boolean;
    columns?: string[];
    delimiter?: string;
    /** 既定 "\r\n" */
    eol?: "\r\n" | "\n";
    quoteAll?: boolean;
  }
  interface CsvWriteOptions extends CsvStringifyOptions {
    /** 既定 "utf8bom"（Excel で文字化けしない） */
    encoding?: Encoding;
    append?: boolean;
  }
  interface Row {
    [column: string]: any;
  }
  interface Csv {
    parse(text: string, options?: CsvParseOptions & { header?: true }): Row[];
    parse(text: string, options: CsvParseOptions & { header: false }): string[][];
    stringify(rows: Row[] | unknown[][], options?: CsvStringifyOptions): string;
    read(src: PathLike | Blob, options?: CsvReadOptions & { header?: true }): Row[];
    read(src: PathLike | Blob, options: CsvReadOptions & { header: false }): string[][];
    write(dest: PathLike, rows: Row[] | unknown[][], options?: CsvWriteOptions): void;
  }
  const csv: Csv;

  // ------------------------------------------------------------------ workbooks

  type CellValue = number | string | boolean | Date | null;

  interface Cell {
    readonly address: string;
    readonly row: number;
    readonly column: number;
    /** 型付きの値（数値・文字列・真偽値・日付・空欄は null） */
    value: CellValue;
    /** 表示形式を適用した文字列 */
    readonly text: string;
    /** "=SUM(A1:A3)" のような数式。なければ null */
    formula: string | null;
    /** 数式を計算する（対応関数は一部） */
    calc(): string;
  }

  interface ToObjectsOptions {
    /** 見出し行の行番号（既定 1）。0 で見出しなし（columns を指定） */
    header?: number;
    columns?: string[];
    /** 空行を除く（既定 true） */
    skipEmpty?: boolean;
    /** 表示形式を適用した文字列で返す */
    text?: boolean;
  }
  interface WriteOptions {
    /** 書き込み開始セル（既定 "A1"） */
    start?: string;
    /** オブジェクト配列のとき見出し行を書く（既定 true） */
    header?: boolean;
    columns?: string[];
  }

  interface Worksheet {
    readonly book: Workbook;
    name: string;
    cell(address: string): Cell;
    cell(row: number, column: number): Cell;
    getValue(address: string): CellValue;
    getValue(row: number, column: number): CellValue;
    setValue(address: string, value: unknown): this;
    setValue(row: number, column: number, value: unknown): this;
    toArrays(options?: { text?: boolean; skipEmpty?: boolean }): CellValue[][];
    toObjects<T = Row>(options?: ToObjectsOptions): T[];
    rows<T = Row>(options?: ToObjectsOptions): T[];
    write(rows: Row[] | unknown[][], options?: WriteOptions): this;
    /** 最終行の下に追記する */
    append(rows: Row[] | unknown[][], options?: WriteOptions): this;
    /** 使用範囲（例 "A1:D20"） */
    readonly dimension: string;
    readonly rowCount: number;
    /** setColumnWidth("A", 20) / setColumnWidth("A:C", 12) */
    setColumnWidth(columns: string, width: number): this;
  }

  interface Workbook {
    readonly path: string | null;
    readonly sheetNames: string[];
    /** シート一覧。book.sheets["売上"] のように名前でも参照できる */
    readonly sheets: Worksheet[] & { [name: string]: Worksheet | undefined };
    sheet(nameOrIndex: string | number): Worksheet | null;
    addSheet(name: string): Worksheet;
    removeSheet(sheet: string | Worksheet): void;
    /** 保存。省略時は開いたファイルに上書き */
    save(dest?: PathLike): this;
    toArrayBuffer(): ArrayBuffer;
    toBlob(): Blob;
    close(): void;
  }

  interface Workbooks {
    /** .xlsx を開く（パス・ハンドル・File・Blob・ArrayBuffer） */
    open(src: PathLike | Blob | ArrayBuffer | ArrayBufferView): Workbook;
    /** 新しいブックを作る（最初の addSheet が既定シートを置き換える） */
    create(): Workbook;
    /** 1 → "A" */
    columnName(n: number): string;
    /** (行, 列) → "B3" */
    cellName(row: number, column: number): string;
  }
  const workbooks: Workbooks;

  interface ObjectConstructor {
    groupBy<K extends PropertyKey, T>(items: Iterable<T>, keySelector: (item: T, index: number) => K): Partial<Record<K, T[]>>;
  }
  interface ArrayConstructor {
    fromAsync<T, U = T>(iterable: AsyncIterable<T> | Iterable<T | PromiseLike<T>>, mapFn?: (value: T, index: number) => U): Promise<U[]>;
  }
}
